"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8912],{45473:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"RockController","desc":"Renders Rock Hazards. On `RockSpawn` it takes a pooled copy of the rock model,\\nscales it, applies the biome look, and moves + spins it every frame with\\n`RockMath.positionAt` (the server\'s formula). On `RockRemoved` it plays the\\nVFX/SFX for the reason and returns the model to the pool. It also shows the\\n`ShieldDome` beams only while the shield is above 0.","realm":["Client"],"source":{"line":12,"path":"src/StarterPlayer/StarterPlayerScripts/RockController.client.luau"}}')}}]);